code:
// ── 🔒 sesion-guardia · F4.2 · no enseñar puertas que no se pueden abrir ──────────────────────────
//
//   game.guardia.on()       · instalar (viene puesto al ejecutar el snippet)
//   game.guardia.off()      · devolver el motor EXACTAMENTE como estaba
//   game.guardia.estado()   · qué permisos se vieron y qué atajos están tapados
//
// ⚠️ ESTO NO PROHÍBE NADA, Y NO PRETENDE HACERLO. Prohibir es cosa de `server.py`: `POST
// /api/snippets` contesta 403 a quien no tenga `snippet.editar_sistema` aunque abra el panel desde la
// consola (F1). Aquí solo se evita enseñarle a un invitado una puerta que no puede abrir.
//
// LO VISIBLE NO LO ESCONDE ESTE SNIPPET, lo esconde `web/style.css` con `[data-solo-si=<permiso>]`
// contra el `data-puede` que pone la propia página. Es a propósito: el CSS llega con el documento y
// un snippet llega después de bajarlo por `fetch`, así que si escondiera él habría medio segundo —en
// una máquina lenta, bastante más— con el panel de Código a la vista. Nacer escondido y destaparse
// es el mismo «fallar hacia cerrado» de `VOXELFORGE_PUBLICO`.
//
// LO QUE EL CSS NO PUEDE HACER ES ESTO: los ATAJOS DE TECLADO. Alt+C seguiría abriendo un panel
// invisible, y peor, se quedaría abierto: el manejador de Esc mira `#snip-modal.hidden`, que sería
// `false`, así que Esc dejaría de soltar el ratón y de cerrar el Mundo mientras dura el equívoco.
//
// CÓMO SE DESENGANCHA SIN TOCAR `app.js`: el manejador del editor es UN `keydown` en `window`
// (app.js:3877 para Alt+C, :3894 para Alt+A). Basta con otro sobre el MISMO `window` pero EN
// CAPTURA: la captura corre antes que cualquier manejador de burbuja, y `stopImmediatePropagation()`
// corta ahí. No hay `fn._orig` que guardar ni función que envolver, así que `off()` es un
// `removeEventListener` y el motor queda byte a byte — la ley de oro, por el camino corto.
//
// ⚠️ `off()` deshace lo de AQUÍ, no lo del CSS: los paneles siguen escondidos para quien no tenga el
// permiso, porque eso nunca lo hizo este snippet. Lo que `off()` devuelve son los atajos.

const G = (window.game = window.game || {});
const M = (G.guardia = G.guardia || {});

// Cada atajo, con el permiso que hace falta para usarlo. El `code` es la tecla FÍSICA por el mismo
// motivo que en `app.js`: con Alt pulsado `e.key` llega compuesto en varios teclados.
M.ATAJOS = [
  { code: 'KeyC', permiso: 'snippet.editar_sistema', que: 'Alt+C · panel de código' },
  { code: 'KeyD', permiso: 'snippet.editar_sistema', que: 'Alt+D · código en dos columnas' },
  { code: 'KeyA', permiso: 'agente.editar',          que: 'Alt+A · panel de agentes' },
];

// ⛔ El estado vive en el módulo, NUNCA en el closure: reejecutar el snippet crea otro ámbito, y con
// el manejador escondido en el anterior no habría forma de quitarlo. Con esto, la segunda pasada
// encuentra el de la primera y lo retira antes de poner el suyo.
M.permisos = M.permisos || [];
M._mano = M._mano || null;

M.puede = function (p) { return M.permisos.indexOf(p) >= 0; };

M.tapados = function () {
  return M.ATAJOS.filter(function (a) { return !M.puede(a.permiso); }).map(function (a) { return a.que; });
};

M.off = function () {
  if (!M._mano) return false;
  window.removeEventListener('keydown', M._mano, true);   // `true` = el MISMO capture con el que se puso
  M._mano = null;
  return true;
};

M.on = function () {
  M.off();                                                // idempotente: nunca dos manejadores apilados
  M._mano = function (e) {
    if (!e.altKey || e.ctrlKey || e.metaKey) return;
    for (const a of M.ATAJOS) {
      if (e.code !== a.code || M.puede(a.permiso)) continue;
      // Se traga la tecla entera: `preventDefault` para que el navegador no haga lo suyo con Alt, y
      // `stopImmediatePropagation` para que no llegue al manejador del editor ni al del Mundo. Sin
      // aviso en consola a propósito — decirle a alguien qué atajo se le ha tapado es enseñarle la
      // puerta, que es justo lo que se estaba evitando.
      e.preventDefault();
      e.stopImmediatePropagation();
      return;
    }
  };
  window.addEventListener('keydown', M._mano, true);
  return true;
};

M.estado = function () {
  return { permisos: M.permisos.slice(), puesto: !!M._mano, tapados: M.tapados() };
};

// `window.vfYo` la deja la propia página (`web/index.html`), que pregunta `GET /api/yo` antes de que
// `app.js` termine de arrancar. Se reaprovecha en vez de volver a preguntar: son los mismos permisos
// y una petición menos en la carga del Mundo, que es donde se cuentan los milisegundos. Si no está
// —una página que aún no lleve esa línea— se pregunta aquí.
//
// ⚠️ «No se sabe» (`null`) NO es «no puede» (`[]`), y por eso la respuesta se distingue de la lista
// vacía. Si la pregunta falla, aquí se falla HACIA ABIERTO: los atajos se quedan como estaban. Es
// justo al revés que el CSS, y a propósito — dejar sin Alt+C al dueño por un parpadeo de red es un
// destrozo, y el invitado al que se le colase el atajo abriría un panel que el CSS sigue tapando y
// cuyo guardado contesta 403. La cerradura está en `server.py`; esto es la cortina.
let vistos = null;
try {
  vistos = await (window.vfYo || fetch('/api/yo', { cache: 'no-store' })
    .then(function (r) { return r.ok ? r.json() : null; })
    .then(function (d) { return (d && ((d.yo && d.yo.permisos) || d.permisos)) || null; }));
} catch (e) {
  console.warn('sesion-guardia: no se pudo saber quién eres, los atajos se quedan como estaban:',
               e && e.message);
}

if (vistos) {
  M.permisos = vistos;
  if (M.tapados().length) M.on(); else M.off();
}
